// Only current execution inputs are directly rehashed. The independently
// reviewed history checkpoint is a descriptor, never flattened into this map.
function reader(){const bindings={},seen=new Map();const bytes=async(f,h)=>{const k=path.resolve(f);if(seen.has(k)){if(h)assert.equal(seen.get(k).sha256,h,f);return seen.get(k).bytes;}const b=await fs.readFile(f),digest=sha(b);if(h)assert.equal(digest,h,f);seen.set(k,{bytes:b,sha256:digest});mergeBindings(bindings,{[f]:digest});return b;};
 const r={bindings,bytes,read:async f=>JSON.parse(await bytes(f)),bound:async d=>{descriptor(d);return JSON.parse(await bytes(d.path,d.sha256));},map:async m=>{for(const[f,h]of Object.entries(m))await bytes(f,h);},finish:async()=>{for(const[f,d]of seen)assert.equal(sha(await fs.readFile(f)),d.sha256,f);}};return r;
}
async function bindTools(r,rt){await r.map(rt.toolchainBindings);const c=await build({entryPoints:[SELF],bundle:true,packages:'external',write:false,metafile:true,platform:'node',format:'esm',logLevel:'silent'});for(const f of Object.keys(c.metafile.inputs))await r.bytes(f);}
async function review(r,d,status,key,subject){const q=await r.bound(d);assert.equal(q.status,status);assert.deepEqual(q.errors,[]);assert.deepEqual(q[key],subject);assert.equal(q.newSearches??q.newGameplaySearches,0);return q;}
async function qualification(r,d){const q=await r.bound(d);assert.equal(q.status,'INDEPENDENT_EARLY_CLEAR_SUPPLEMENTAL_IRREGULAR_BATCH_TASK_PASS');assert.deepEqual(q.errors,[]);assert.equal(q.searchAlgorithmChanged,false);assert.equal(q.failedOriginalRetryAllowed,false);for(const k of ['newRealConstructions','newSearches','publicClaimsStarted'])assert.equal(q[k],0);for(const f of [SELF,TARGETS[2].entry,TARGETS[3].entry,'tools/daily-challenge/formal-v4/replaced-irregular-region-stock.mjs','tools/daily-challenge/formal-v4/replaced-irregular-reference.mjs','tools/daily-challenge/formal-v4/plan-history-adapter-v4.mjs','tools/daily-challenge/formal-v4/supplemental-failed-parent-evidence.mjs','tools/daily-challenge/formal-v4/canonical-history-path-compiled.mjs'])assert(q.toolBindings[f]);await r.map(q.toolBindings);return q;}
async function validateReference(rt,r,ref,recipe){const q=await r.bound(ref.reference),b=qualifyReplacedIrregularReference(rt,q,{...recipe,...ref});b.prefixReplay=replayLongPrefix(rt,q.level,b.prefixDrags);
 for(const asset of b.nativeAssetPaths)await r.bytes(path.join('public',asset.replace(/^\/+/,'')));return b;
}
const nearest=(l,rows)=>rows.reduce((n,q)=>Math.max(n,compareLayouts(l,q.level).footprintSimilarity),0);
function comparisons(l,b,rt,pool,eligible){return{reference:compareLayouts(l,b.level).footprintSimilarity,source:compareLayouts(l,rt.LEVELS.find(q=>q.id===b.sourceLevelId)).footprintSimilarity,selected:nearest(l,pool.selected),old450:nearest(l,pool.old450),history:nearest(l,pool.history),newBatch:nearest(l,eligible.filter(q=>branch(q)!==branch(b)))};}
const nearPass=s=>Object.entries(s).every(([k,v])=>v<=(k==='source'?.55:k==='old450'?.75:.65)+1e-12);
export function sameEarlyClearReference(a,b,scope){return !!(a?.path&&b?.path&&a.sha256===b.sha256&&canonicalHistoryPath(a.path,scope)===canonicalHistoryPath(b.path,scope));}
function stockState(pool,blueprints,scope){const state={partitions:new Set([...pool.history,...pool.selected].map(q=>partition(q.level))),formed:new Map(),shapes:[]};for(const q of pool.history)for(const b of blueprints)if(q.sourceLevelId===b.sourceLevelId&&sameEarlyClearReference(q.reference,b.canonicalReference,scope)){const key=branch(b),f=designFingerprints(q.level);state.shapes.push({key,f});state.formed.set(key,[...(state.formed.get(key)??[]),f]);}return state;}
export function assertRegionShapeProfile(blocks,profile,seed){assert(['balanced','bar-mix','axial-bars'].includes(profile));integer(seed,1,Number.MAX_SAFE_INTEGER);const n=blocks.length,bars=blocks.filter(b=>longBar(b.shape)),singles=blocks.filter(b=>b.shape.length===1).length;
 if(profile==='bar-mix')assert(bars.length>=Math.ceil(.4*n)&&bars.length<=Math.floor(.65*n)&&singles<=2);
 if(profile==='axial-bars'){assert(bars.length>=Math.ceil(.65*n)&&bars.length<=Math.floor(.85*n)&&singles<=1);assert(bars.filter(b=>(Math.max(...b.shape.map(p=>p[1]))===0)===((seed&1)===0)).length>=Math.ceil(.5*n));}return true;}
function assertStock(built,b,seed=built.provenance?.seed??b.seed){assertTargetConstructionAccounting(built,2);if(built.partition.ok)assertRegionShapeProfile(built.partition.blocks,b.shapeProfile,seed);if(!built.ok)return;assert.equal(built.constructionAccounting.version,'late-region-static-construction-v1');assert.deepEqual(built.level.gates,b.allReferenceGates);assert.equal(boardBaselineSha256(built.level),b.boardOutlineSha256);assert.equal(built.levelSha256,levelSha256(built.level));assert.deepEqual(built.level.blocks.filter(x=>b.fixedBlocks.some(f=>f.id===x.id)),b.fixedBlocks);assertSameUniqueCells(built.level.blocks.filter(x=>!b.fixedBlocks.some(f=>f.id===x.id)).flatMap(absoluteCells),b.region.cells);assert.deepEqual(built.prefixDrags,b.prefixDrags);assert.equal(built.iceDeclaration,undefined);}

async function historyListing(scope){const listing={};for(const root of scope.roots){const files=[];const visit=async dir=>{for(const e of await fs.readdir(dir,{withFileTypes:true})){assert(!e.isSymbolicLink(),'History listing must not follow a nested alias');const f=path.join(dir,e.name);if(e.isDirectory())await visit(f);else if(e.isFile())files.push(f);}};if(await exists(root.physicalPath))await visit(root.physicalPath);listing[root.id]=files;}return listing;}
// An intermediate sealed-facts view is not a live filesystem observation.
// Every phase separately checks the complete no-follow live membership via members().
export function declaredHistoryMembership(h,delta){const scope=h.bundle.scope,compiled=compileCanonicalHistoryPath(scope),listing=Object.fromEntries(scope.roots.map(x=>[x.id,[]])),seen=new Set();
 for(const f of [...h.bundle.files,...delta.files])if(f.rootId!==null){assert(Object.hasOwn(listing,f.rootId));const c=compiled.canonical(f.path);assert(!seen.has(c),'Duplicate declared history member');seen.add(c);listing[f.rootId].push(f.path);}return listing;}
async function history(r,p){assert.equal(p.historyScope.roots.length,7);assert.deepEqual((await Promise.all(p.historyScope.roots.map(x=>realPathWithSuffix(x.physicalPath)))).sort(),(await Promise.all(HISTORY_LEDGER_ROOTS.map(realPathWithSuffix))).sort());let h=await consumePlanHistory({checkpoint:p.history,review:p.historyReview,expectedScope:p.historyScope,readBytes:r.bytes});
 assert(Array.isArray(p.historyDeltas??[]));for(const x of p.historyDeltas??[]){descriptor(x.descriptor);descriptor(x.declaredOwner.definition);const delta=await r.bound(x.descriptor);h=await mergePlanHistoryDelta(h,{...x,listing:declaredHistoryMembership(h,delta),readBytes:r.bytes});}
 // The immutable failed packets are a separately reviewed comparison overlay,
 // never ledger additions or a replacement history head. Current role checks
 // run inside the helper after all declared deltas have been consumed.
 assertSupplementalContextPins(p);const supplemented=await readSupplementalFailedParentEvidence(h,{...p.supplementalFailedParents,role:'failed-parent',readBytes:r.bytes,qualificationOnly:false});
 mergeBindings(r.bindings,supplemented.fileBindings);return supplemented.state;}
async function members(h,allowed=[]){const scope=h.bundle.scope,additions=[...new Set(allowed)].map(file=>{const canonical=canonicalHistoryPath(path.resolve(file),scope),root=scope.roots.find(x=>canonical.startsWith(canonicalHistoryPath(x.physicalPath,scope)+'/'));assert(root,'Addition outside seven history roots');return{path:path.resolve(file),rootId:root.id};});return assertPlanHistoryMembers(h,await historyListing(scope),additions);}
export function assertLegacyAllowlist(allowlist){assert.deepEqual(allowlist,[],'Future early-clear batches do not inherit the closed legacy198 exception');return true;}
